import{_ as s,o as a,c as e,ak as h}from"./chunks/framework.DxrHb2fb.js";const c=JSON.parse('{"title":"代码着色","description":"","frontmatter":{},"headers":[],"relativePath":"runtime/code-highlight.md","filePath":"runtime/code-highlight.md","lastUpdated":1789465542000}'),t={name:"runtime/code-highlight.md"};function n(l,i,p,d,k,r){return a(),e("div",null,[...i[0]||(i[0]=[h(`<h1 id="代码着色" tabindex="-1">代码着色 <a class="header-anchor" href="#代码着色" aria-label="Permalink to &quot;代码着色&quot;">​</a></h1><p><code>@xihan-ui/code-highlight</code> 是 <code>HighlighterPort</code> 的自研实现：粗粒度词法着色，零第三方依赖。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createHighlighter } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@xihan-ui/code-highlight&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> highlighter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createHighlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>把它交给<a href="./../components/code-view">代码视图</a>组件的 <code>highlighter</code> prop 即可。组件本身不识别任何具体的着色器，只识别这个端口。</p><h2 id="是否安装" tabindex="-1">是否安装 <a class="header-anchor" href="#是否安装" aria-label="Permalink to &quot;是否安装&quot;">​</a></h2><p>它是各适配器的可选 peer，不随适配器一起安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @xihan-ui/code-highlight</span></span></code></pre></div><p>安装后，<a href="./../components/code-view">代码视图</a>自动着色，不需要写 <code>highlighter</code> prop；不安装时代码视图渲染纯文本，不报错。换成其他实现（典型是接入 Shiki）同样通过 <code>highlighter</code> prop。</p><h2 id="区分范围" tabindex="-1">区分范围 <a class="header-anchor" href="#区分范围" aria-label="Permalink to &quot;区分范围&quot;">​</a></h2><p>只区分五类：注释、字符串、数字、关键字、标点。</p><p>类型名、函数名、属性名这类需要语法树才能区分的内容一概不分：那属于 TextMate 语法一档的工作，本实现不追求。因此同一段代码在这里与在编辑器中的显示不会完全相同，这是预期内的。</p><p>无法识别的语言、超长代码一律返回 <code>null</code>，由调用方原样渲染纯文本。没有着色不等于故障，这是设计上的降级路径。</p><h2 id="更高精度时更换实现" tabindex="-1">更高精度时更换实现 <a class="header-anchor" href="#更高精度时更换实现" aria-label="Permalink to &quot;更高精度时更换实现&quot;">​</a></h2><p><code>highlighter</code> 是一个端口，不是一个实现。把 Shiki、Prism 或其他着色器包装成同一个形状接入，组件侧不需修改：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HighlighterPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  highlight</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">lang</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> readonly</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CodeToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这条端口存在的理由：库不替使用方决定是否为语法高亮付出几百 kB 的体积。默认提供一个够用且无额外代价的实现，需要升级时随时更换。</p><h2 id="不直接内置-shiki-的原因" tabindex="-1">不直接内置 Shiki 的原因 <a class="header-anchor" href="#不直接内置-shiki-的原因" aria-label="Permalink to &quot;不直接内置 Shiki 的原因&quot;">​</a></h2><p>Shiki 需要携带 TextMate 语法与主题数据，体积在几百 kB 量级，且需要异步加载。对文档中偶尔出现一段代码的场景，这个代价不成比例。而对实际构建代码编辑器的使用方，粗粒度着色又不足够：两侧都不应由库代为决定。端口是唯一能同时满足两侧的形态。</p><h2 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to &quot;支持的语言&quot;">​</a></h2><p><code>langSpecOf(lang)</code> 可识别的语言即受支持的语言。传入无法识别的标注返回 <code>null</code>，代码原样渲染。</p><p>流式场景需配合 <code>complete</code> 使用：未闭合的代码随时会变，着色是纯计算但有开销，等闭合后再执行一次更合理。<a href="./../components/code-view">代码视图</a>组件的 <code>highlightWhileStreaming</code> 即为该开关。</p><h2 id="长度上限" tabindex="-1">长度上限 <a class="header-anchor" href="#长度上限" aria-label="Permalink to &quot;长度上限&quot;">​</a></h2><p>超过 <code>HIGHLIGHT_MAX_LENGTH</code> 的代码直接返回 <code>null</code>。着色是同步的，超长输入会阻塞主线程，与其卡顿不如不着色。这个常量是导出的，可读但不可修改：处理超长代码本应在 worker 中进行。</p>`,23)])])}const g=s(t,[["render",n]]);export{c as __pageData,g as default};
